//! Cargo-driven `uxtheme.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x78ac0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff8a000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff8a000000u64)),
        o => panic!("uxtheme-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "import:msimg32", "import:user32", "import:advapi32", "import:gdi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body", "engine:oldnames"],
        "x86_64" => &["engine:wine", "import:msimg32", "import:user32", "import:advapi32", "import:gdi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body", "engine:oldnames"],
        "aarch64" => &["engine:wine", "import:msimg32", "import:user32", "import:advapi32", "import:gdi32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:delayimp_rust", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/uxtheme",
        "dll/win32/uxtheme",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("uxtheme_shims", &["dll/win32/uxtheme/buffer.c", "dll/win32/uxtheme/draw.c", "dll/win32/uxtheme/errinfo.c", "dll/win32/uxtheme/main.c", "dll/win32/uxtheme/metric.c", "dll/win32/uxtheme/msstyles.c", "dll/win32/uxtheme/ncscrollbar.c", "dll/win32/uxtheme/nonclient.c", "dll/win32/uxtheme/property.c", "dll/win32/uxtheme/stylemap.c", "dll/win32/uxtheme/system.c", "dll/win32/uxtheme/themehooks.c", "dll/win32/uxtheme/uxini.c"])
        .rc("dll/win32/uxtheme/uxtheme.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/uxtheme/uxtheme.spec", "uxtheme.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/msimg32/msimg32.spec", "msimg32.dll", "msimg32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
